#!/usr/bin/env node
'use strict';

// One source of truth, distinct manifest resource paths in each execution world.
const fs = require('node:fs');
const path = require('node:path');
const root = path.join(__dirname, '..');
const sources = ['utils/capture-contract.js', 'utils/native-request-template.js'];
const target = path.join(root, 'content/capture-prerequisites.js');
const expected = '// Generated by node scripts/check-capture-bundle.js --write. Do not edit.\n' +
    sources.map(file => `\n// ${file}\n${fs.readFileSync(path.join(root, file), 'utf8')}`).join('');
if (process.argv.includes('--write')) fs.writeFileSync(target, expected);
if (!fs.existsSync(target) || fs.readFileSync(target, 'utf8') !== expected) {
    throw new Error('Stale isolated-world prerequisites. Run node scripts/check-capture-bundle.js --write');
}
console.log('PASS isolated-world prerequisites match canonical sources');
